proposals.new_text:
let post: string;
try {
  post = await generatePost(topic);
  if (!post || post.trim().length < 100) {
    console.error(`[daily-blog] ${new Date().toISOString()} generation returned empty or short content, skipping commit`);
    process.exit(0);
  }
} catch (err) {
  console.error(`[daily-blog] ${new Date().toISOString()} generation failed:`, err);
  process.exit(0);
}
await commitPost(post);
